134 │ export function isTintinwebSubagentsAvailable(): boolean {
135 │   return typeof (globalThis as any)[SUBAGENTS_MANAGER_KEY] !== "undefined";
136 │ }
137 │ 
138 │ /**
139 │  * Check if nicobailon/pi-subagents is loaded by probing its runtime
140 │  * cleanup function stored on globalThis.
141 │  */
142 │ export function isNicobailonSubagentsAvailable(): boolean {
143 │   return typeof (globalThis as any)[NICOBALLON_RUNTIME_KEY] === "function";
144 │ }
145 │ 
146 │ /**
147 │  * Detect which (if any) subagent library is currently loaded.
148 │  * Returns the detected library identifier or null if none found.
